import json, numpy as np, pandas as pd
from common import *
W = json.load(open(f'{BASE}/win_metrics.json')); M = json.load(open(f'{BASE}/method_metrics.json')); R = json.load(open(f'{BASE}/props_metrics.json')); FP = json.load(open(f'{BASE}/final_params.json'))
proj = pd.read_csv(f'{BASE}/projections.csv'); fr = pd.read_pickle(f'{DATA}/fights.pkl'); elo_t = pd.read_csv(f'{BASE}/elo_tuning.csv')
cut = fr.date.max().date()
def md(df, fmt=None, idx=False):
    df = df.copy()
    for c in df.columns:
        if df[c].dtype.kind == 'f': df[c] = df[c].map(lambda v: f'{v:.3f}')
    cols = list(df.columns); s = '| ' + ' | '.join(map(str, cols)) + ' |\n|' + '|'.join(['---'] * len(cols)) + '|\n'
    for _, r in df.iterrows(): s += '| ' + ' | '.join(map(str, r.values)) + ' |\n'
    return s
res = W['res']; d = res['_diff']
L = []
L.append(f"# UFC Fight Night: Allen vs Duncan (2026-10-10) - quick model report\n")
L.append(f"**Data**: Greco1899/scrape_ufc_stats (ufcstats.com scrape, GitHub raw). **Data cutoff (latest event in files): {cut}** (UFC 332: Silva vs. Wang). The repo's own README says a full refresh was done 2025-11-22 and a daily job refreshes new fights; the files I pulled already contain all events through {cut}, so there is no lag for tonight's ten fighters (each fighter's last fight in the data is listed in `data_flags`). All ten fighters were found in the data (Kai Kamaka III matched as 'Kai Kamaka'; Loopy Godinez found directly; Lupita alias also mapped). Any fight after {cut} and before tonight (none expected) would be missing.\n")
L.append("## 1. Win probability\n")
L.append(f"Setup: Elo over all UFC fights (K and a new-fighter boost tuned on pre-2023 fights only: K={elo_t.sort_values('logloss').iloc[0].K:.0f}, boost x{elo_t.sort_values('logloss').iloc[0].boost}). Antisymmetric logistic regression (no intercept, trained on both fighter orders so there is no corner bias) on Elo diff + age, reach, height, log UFC experience, days since last fight, shrunk career rates (sig strikes landed/min, absorbed/min, takedowns landed/15, takedown defense, sub attempts/15), last-3 win rate and last-3 sig-strike differential. Every feature is point-in-time (only fights on strictly earlier dates; cards are predicted before any card result is applied). Trained on 2011-01-01 to 2022-12-31 ({W['n_train']} fights), L2 strength chosen on a 2021-22 time-split (C={W['C']}). **Holdout: 2023-01-01 to {W['hold_end']}, n={W['n_hold']} decisive fights** (draws/NC excluded).\n")
t = pd.DataFrame([{ 'model': k, 'log loss': v['logloss'], 'Brier': v['brier'], 'accuracy': v['accuracy'], 'n': v['n']} for k, v in res.items() if not k.startswith('_')])
L.append(md(t))
L.append(f"\nLog-loss gain of the full model vs raw Elo: {d['ll_gain_vs_elo']:.4f} (bootstrap 95% CI {d['ll_gain_vs_elo_ci'][0]:.4f} to {d['ll_gain_vs_elo_ci'][1]:.4f}); vs 50%: {d['ll_gain_vs_50']:.4f} (CI {d['ll_gain_vs_50_ci'][0]:.4f} to {d['ll_gain_vs_50_ci'][1]:.4f}). **The model beats both Elo and the 50% baseline on the holdout; Elo alone beats 50% only modestly (log loss {res['Elo only (raw expectation)']['logloss']:.4f} vs 0.6931).** No betting-market odds were available, so I cannot say whether it beats the market; a typical closing-line log loss is lower than this.\n")
L.append("Holdout by year (stability check):\n"); L.append(md(pd.DataFrame(W['by_year'])[['year', 'n', 'model_ll', 'elo_ll', 'base_ll', 'model_acc', 'elo_acc']]))
L.append("\nCalibration, full model, 5 equal-count bins on P(fighter A wins) (A/B order is arbitrary in the source files, so this is mostly a lopsidedness test):\n"); L.append(md(pd.read_csv(f'{BASE}/calib_win_full.csv')))
L.append("\nCalibration, favourite-oriented (P(favourite wins), 5 bins):\n"); L.append(md(pd.read_csv(f'{BASE}/calib_win_fav.csv')))
L.append("\nCalibration, raw Elo, 5 bins:\n"); L.append(md(pd.read_csv(f'{BASE}/calib_win_elo.csv')))
L.append("\nThe model is slightly under-confident at the extremes (e.g. top bin predicted 0.70, observed 0.76). Logistic coefficients per 1 SD of each feature (positive favours fighter A): " + ', '.join(f"{k} {v:+.2f}" for k, v in W['coef_std'].items()) + ".\n")
L.append("Tonight's win probabilities come from the same model refit on all data through the cutoff (same hyperparameters).\n")
L.append("## 2. Method / duration\n")
L.append(f"Each fighter's KO-for, KO-against, sub-for, sub-against rates (per fight, 3-round-equivalent: a finish after round 3 in a 5-round fight counts as 'went 3 rounds') are shrunk toward the point-in-time weight-class x gender base rate (prior strength n0={M['n0']:.0f} fights, fighter-signal multiplier alpha={M['alpha']}; tuned on 2021-22). Fight P(KO), P(sub) = sum over both fighters; P(distance) = remainder. 5-round bouts: P(survive rounds 4-5 | survived 3) = {FP['late_stats']['S45']:.3f} from 5-round fights 2018 onward (n reaching round 4 = {FP['late_stats']['n_reach4']}), and fight time is sampled from empirical finish-time quantiles. Per-fighter p_ko_for/p_sub_for come from a 2x3 (winner x method) table reconciled by iterative proportional fitting to the model win probability and the fight-level method totals.\n")
mt = pd.DataFrame([{'model': k, 'multiclass log loss': M[k]['mlogloss'], 'P(distance) log loss': M[k]['dist_logloss'], 'P(distance) Brier': M[k]['dist_brier'], 'KO Brier': M[k]['ko_brier'], 'Sub Brier': M[k]['sub_brier']} for k in ('fighter+division', 'division base only', 'global base only')])
L.append(f"Holdout (n={M['n_hold']} fights, 3-round-equivalent outcome DEC/KO/SUB):\n"); L.append(md(mt)); L.append(f"\nConstant P(distance) log loss: {M['const_dist_logloss']:.4f}. Fighter-level info helps (0.667 vs 0.685 division-only vs 0.694 global) but the gain is modest.\n")
